"""Bounded video transport counters; no payloads, URLs or user input retained."""
import json
import os
from pathlib import Path
import tempfile
import time
import uuid


DIAGNOSTICS_PATH = Path("/run/selkies-video/diagnostics.json")
CLIENT_AV1_ERROR_CODES = frozenset({
    "CLIENT_INSECURE_CONTEXT", "CLIENT_WEBCODECS_UNAVAILABLE",
    "CLIENT_CODEC_UNSUPPORTED", "CLIENT_CAPABILITY_TIMEOUT", "CLIENT_CAPABILITY_ERROR",
    "CLIENT_SEQUENCE_UNSUPPORTED", "CLIENT_CONFIG_TIMEOUT", "CLIENT_INVALID_BITSTREAM",
    "CLIENT_INVALID_PACKET", "CLIENT_GEOMETRY_MISMATCH", "CLIENT_DECODE_FAILED",
    "CLIENT_FIRST_FRAME_TIMEOUT", "CLIENT_OUTPUT_TIMEOUT", "CLIENT_QUEUE_OVERFLOW",
})


class VideoSessionMetrics:
    """One counter per capture, measured before fan-out to multiple viewers.

    Bytes include the application's video packet header, but not WebSocket/TLS
    framing. Frames count distinct adjacent frame IDs, not stripes or viewers.
    Hardware remains unknown unless a native runtime explicitly reports it.
    """

    def __init__(self, encoder, width, height, target_fps, use_cpu, clock=time.monotonic):
        self.clock = clock
        self.started = clock()
        self.started_at = time.time()
        self.stopped = None
        self.session_id = uuid.uuid4().hex
        self.encoder = encoder
        self.width, self.height = width, height
        self.target_fps = target_fps
        self.requested_use_cpu = bool(use_cpu)
        self.frames = self.bytes = 0
        self.codec = None
        self.hardware = None
        self.runtime_info = {}
        self.native_statistics = None
        self.first_sent_ms = None
        self.last_frame_id = None
        self.last_frame_at = None
        self.last_key_at = None
        self.last_key_interval = None
        self.key_interval_sum = 0.0
        self.key_interval_max = 0.0
        self.key_intervals = self.keyframes = 0
        self.sample_time = self.started
        self.sample_frames = self.sample_bytes = 0
        self.fps = self.bitrate = self.peak_fps = self.peak_bitrate = 0.0
        self.sample_interval = self.peak_bitrate_interval = None

    def record(self, packet, frame_id):
        if self.stopped is not None or not packet:
            return
        now = self.clock()
        self.bytes += len(packet)
        self.codec = {0: "h264", 3: "jpeg", 4: "h264", 5: "h265", 6: "av1"}.get(packet[0], self.codec)
        if frame_id == self.last_frame_id:
            return
        self.last_frame_id = frame_id
        self.frames += 1
        self.last_frame_at = now
        if self.first_sent_ms is None:
            self.first_sent_ms = (now - self.started) * 1000
        if packet[0] in (0, 4, 5, 6) and len(packet) > 1 and packet[1] == 1:
            self.keyframes += 1
            if self.last_key_at is not None:
                interval = now - self.last_key_at
                self.last_key_interval = interval
                self.key_interval_sum += interval
                self.key_interval_max = max(self.key_interval_max, interval)
                self.key_intervals += 1
            self.last_key_at = now

    def update_runtime(self, info, statistics=None):
        if isinstance(info, dict):
            # Explicitly whitelist scalar fields; omit paths and native errors.
            self.runtime_info = {key: info[key] for key in (
                "codec", "hardware", "encoder", "bit_depth", "fullcolor", "striped",
                "capture_backend", "zero_copy"
            ) if key in info and isinstance(info[key], (str, int, float, bool, type(None)))}
            if info.get("codec") in ("av1", "h265", "h264"):
                self.codec = info["codec"]
            self.hardware = info.get("hardware") if isinstance(info.get("hardware"), bool) else None
        else:
            self.hardware = None
            self.runtime_info = {}
        if isinstance(statistics, dict):
            self.native_statistics = statistics

    def stop(self):
        if self.stopped is None:
            self.stopped = self.clock()

    def snapshot(self):
        now = self.clock() if self.stopped is None else self.stopped
        elapsed = max(0.0, now - self.started)
        interval = now - self.sample_time
        if interval >= 0.5:
            self.fps = (self.frames - self.sample_frames) / interval
            self.bitrate = (self.bytes - self.sample_bytes) * 8 / interval
            self.peak_fps = max(self.peak_fps, self.fps)
            if self.bitrate > self.peak_bitrate:
                self.peak_bitrate = self.bitrate
                self.peak_bitrate_interval = interval
            self.sample_interval = interval
            self.sample_time, self.sample_frames, self.sample_bytes = now, self.frames, self.bytes
        return {
            "session_id": self.session_id, "active": self.stopped is None,
            "measurement": "server_video_bytes_before_fanout",
            "requested_encoder": self.encoder, "requested_use_cpu": self.requested_use_cpu,
            "codec": self.codec, "hardware": self.hardware,
            "width": self.width, "height": self.height, "target_fps": self.target_fps,
            "started_at": self.started_at, "elapsed_seconds": round(elapsed, 3),
            "frames": self.frames, "bytes": self.bytes,
            "first_sent_ms": None if self.first_sent_ms is None else round(self.first_sent_ms, 3),
            "fps": round(self.fps, 3), "average_fps": round(self.frames / elapsed, 3) if elapsed else 0,
            "peak_fps": round(self.peak_fps, 3), "bitrate_bps": round(self.bitrate, 3),
            "average_bitrate_bps": round(self.bytes * 8 / elapsed, 3) if elapsed else 0,
            "peak_bitrate_bps": round(self.peak_bitrate, 3),
            "sample_interval_seconds": self.sample_interval,
            "peak_bitrate_window_seconds": self.peak_bitrate_interval,
            "keyframes": self.keyframes,
            "last_keyframe_interval_seconds": self.last_key_interval,
            "average_keyframe_interval_seconds": self.key_interval_sum / self.key_intervals if self.key_intervals else None,
            "max_keyframe_interval_seconds": self.key_interval_max if self.key_intervals else None,
            "last_frame_age_seconds": now - self.last_frame_at if self.last_frame_at is not None else None,
            "runtime": self.runtime_info.copy(), "native": self.native_statistics,
        }


def write_snapshot(displays, path=DIAGNOSTICS_PATH):
    """Replace a small runtime-only snapshot atomically, with owner-only access."""
    path = Path(path)
    payload = {"schema_version": 1, "updated_at": time.time(), "displays": displays}
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=path.parent,
                                         prefix=".diagnostics-", delete=False) as output:
            temporary = output.name
            json.dump(payload, output, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
            output.write("\n")
        os.replace(temporary, path)
    finally:
        if temporary and os.path.exists(temporary):
            os.unlink(temporary)
